import React, { useMemo, useState, useEffect } from "react";
import {
  Section,
  Timeline,
  ExperienceItem,
  ExperienceContent,
  TimelineDot,
  Duration,
  Description,
  CardHeader,
  RoleTitle,
  RolePeriod,
  OrgLabel,
  OrgColumn,
  OrgLogo,
  OrgDescription,
  TagsContainer,
  Tag,
  FilterContainer,
  FilterButton,
  SectionContainer,
  FiltersBar,
  MobileOnlyBr,
  SmallMobileOnlyBr,
  TimelineDotDesktop,
} from "./Experience.styles";
import { experiences } from "./Experience.data";
import SectionDots from "../../components/SectionDots";

const Experience: React.FC = () => {
  const [activeFilter, setActiveFilter] = useState<string>("all");
  const [activeYear, setActiveYear] = useState<string>("");

  const years = useMemo(() => {
    const yearSet = new Set<string>();
    experiences.forEach((exp) => {
      const dur = exp.roles[0]?.duration || "";
      const match = dur.match(/\b(20\d{2})\b/);
      if (match) yearSet.add(match[1]);
    });
    return Array.from(yearSet).sort((a, b) => Number(b) - Number(a));
  }, []);

  useEffect(() => {
    if (years.length) {
      setActiveYear(years[0]);
    }
  }, [years]);

  const filteredExperiences = experiences.filter((exp) => {
    if (activeFilter === "all") return true;
    return exp.tags?.includes(activeFilter.toUpperCase());
  });

  useEffect(() => {
    const handleScroll = () => {
      for (const year of years) {
        const el = document.getElementById(`year-${year}`);
        if (el) {
          const rect = el.getBoundingClientRect();
          if (rect.top <= 160 && rect.bottom >= 160) {
            setActiveYear(year);
            break;
          }
        }
      }
    };
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, [years]);

  const handleYearChange = (yearId: string) => {
    setActiveYear(yearId);
    const el = document.getElementById(`year-${yearId}`);
    if (el) {
      el.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  };

  const yearOfExp = (exp: typeof experiences[number]) => {
    const dur = exp.roles[0]?.duration || "";
    const match = dur.match(/\b(20\d{2})\b/);
    return match ? match[1] : "";
  };

  const renderWithResponsiveBreaks = (text: string) => {
    const tokens = text.split(/(\[\[BR_768\]\]|\[\[BR_480\]\])/g);
    return tokens.map((tok, i) => {
      if (tok === "[[BR_768]]") return <MobileOnlyBr key={`br768-${i}`} />;
      if (tok === "[[BR_480]]") return <SmallMobileOnlyBr key={`br480-${i}`} />;
      return tok;
    });
  };

  return (
    <Section id="experience">
      <SectionContainer>
        <FiltersBar>
          <FilterContainer>
            <FilterButton active={activeFilter === "all"} onClick={() => setActiveFilter("all")}>
              All
            </FilterButton>
            <FilterButton active={activeFilter === "cse"} onClick={() => setActiveFilter("cse")}>
              CSE
            </FilterButton>
            <FilterButton active={activeFilter === "edu"} onClick={() => setActiveFilter("edu")}>
              EDU
            </FilterButton>
          </FilterContainer>
          <YearFilterRow>
            <YearFilterPill active={activeYear === "all"} onClick={() => setActiveYear("all")}>
              All years
            </YearFilterPill>
            {["2025", "2024", "2023", "2022"].map((year) => (
              <YearFilterPill key={year} active={activeYear === year} onClick={() => setActiveYear(year)}>
                {year}
              </YearFilterPill>
            ))}
          </YearFilterRow>
        </FiltersBar>
        <Timeline>
          {filteredExperiences
            .filter((exp) => activeYear === "all" || exp.roles.some((r) => r.duration?.includes(activeYear)))
            .map((exp, index) => (
            <div key={index} style={{ position: "relative" }}>
              <ExperienceItem isLeft>
                <OrgColumn>
                  <OrgLabel>{exp.organization}</OrgLabel>
                  <OrgDescription>{renderWithResponsiveBreaks(exp.orgDescription || "")}</OrgDescription>
                  {exp.logoUrl ? (
                    <OrgLogo>
                      <img src={exp.logoUrl} alt={`${exp.organization} logo`} />
                    </OrgLogo>
                  ) : null}
                  <TimelineDot />
                </OrgColumn>
                <ExperienceContent isLeft>
                  {exp.roles.map((role, rIdx) => (
                    <div key={rIdx} style={{ marginBottom: rIdx < exp.roles.length - 1 ? 12 : 0 }}>
                      <RoleTitle>
                        {role.title}
                        {role.duration && <RolePeriod>{role.duration}</RolePeriod>}
                      </RoleTitle>
                      {rIdx === 0 && exp.tags && (
                        <TagsContainer>
                          {exp.tags.map((tag, tIdx) => (
                            <Tag key={tIdx} variant={tag.toLowerCase() as "cse" | "edu"}>
                              {tag}
                            </Tag>
                          ))}
                        </TagsContainer>
                      )}
                      <Description>{role.description}</Description>
                    </div>
                  ))}
                </ExperienceContent>
                <TimelineDotDesktop />
              </ExperienceItem>
            </div>
          ))}
        </Timeline>
      </SectionContainer>
    </Section>
  );
};

export default Experience;
